mapper.select:
SELECT MEMBER_ID, LOGIN_ID, PASSWORD, NICKNAME, EMAIL, STATUS
FROM MEMBER
WHERE MEMBER_ID = #{memberId}

mapper.update:
UPDATE MEMBER
SET NICKNAME = #{nickname},
    EMAIL = #{email},
    PHONE = #{phone}

    , PASSWORD = #{newPassword}

WHERE MEMBER_ID = #{memberId}

mapper.select:
SELECT COUNT(*) FROM EMAIL_AUTH
WHERE EMAIL = #{email}
  AND PURPOSE = #{purpose}
  AND CREATED_AT > SYSDATE - 1/1440

mapper.update:
UPDATE MEMBER
SET PASSWORD = #{password}
WHERE MEMBER_ID = #{memberId}

mapper.select:
SELECT * FROM ( SELECT a.*, ROWNUM AS RN FROM ( SELECT ROW_NUMBER() OVER (ORDER BY l.LIFE_ID) AS LIFE_NO, l.LIFE_ID, c.NAME_KO AS BIRTH_COUNTRY_NAME, l.BIRTH_YEAR, l.DEATH_AGE, l.DEATH_CAUSE, TO_CHAR(l.ENDED_AT, 'YYYY-MM-DD') AS ENDED_AT, (SELECT COUNT(*) FROM LIFE_QUEST q WHERE q.LIFE_ID = l.LIFE_ID) AS QUEST_TOTAL, (SELECT COUNT(*) FROM LIFE_QUEST q WHERE q.LIFE_ID = l.LIFE_ID AND q.ACHIEVED = 'Y') AS QUEST_DONE, (SELECT NVL(SUM(p.AMOUNT), 0) FROM POINT_HISTORY p WHERE p.LIFE_ID = l.LIFE_ID AND p.REASON = 'QUEST') AS EARNED_POINT FROM LIFE l JOIN COUNTRY c ON c.COUNTRY_CODE = l.BIRTH_COUNTRY WHERE l.MEMBER_ID = #{memberId} AND l.STATUS = 'ENDED'
ORDER BY l.DEATH_AGE DESC NULLS LAST, l.LIFE_ID DESC ORDER BY l.LIFE_ID DESC
) a WHERE ROWNUM <= #{end} ) WHERE RN > #{start}

mapper.update:
UPDATE MEMBER_TRAIT mt
SET TRAIT_LEVEL = TRAIT_LEVEL + 1
WHERE mt.MEMBER_ID = #{memberId}
  AND mt.TRAIT_ID = #{traitId}
  AND mt.TRAIT_LEVEL < (SELECT t.MAX_LEVEL FROM TRAIT t WHERE t.TRAIT_ID = mt.TRAIT_ID)
